std::vector<Node> nodes;
nodes.reserve(rt.number_of_vertices());

for (auto vit = rt.finite_vertices_begin(); vit != rt.finite_vertices_end(); ++vit) {
    // Position
    const Point pos = vit->point().point();

    // Mass (derived from weight)
    const double weight = vit->point().weight();
    const double mass = (time != 0.0) ? weight / (2.0 * time) : 0.0;

    // Velocity (using an incident cell)
    const Vector vel = velocity(vit->cell());

    // Count incident edges shorter than the threshold
    int edge_cnt = 0;
    auto ec = rt.incident_edges(vit);
    if (ec != nullptr) {
        auto done = ec;
        do {
            if (is_small_edge(rt, *ec, threshold)) {
                ++edge_cnt;
            }
            ++ec;
        } while (ec != done);
    }

    // Determine node type
    const NodeType type = type_from_edge_count(edge_cnt);

    nodes.emplace_back(Node{pos, vel, mass, type});
}
return nodes;

